   303|async function runSupabaseResetOwnerPassword(input: Record<string, unknown>): Promise<Record<string, unknown>> {
   304|  const email = readTrimmed(input.email).toLowerCase();
   305|  const newPassword = readTrimmed(input.newPassword) || readTrimmed(input.password);
   306|  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
   307|    throw new Error('A valid owner email is required for supabase_reset_owner_password.');
   308|  }
   309|  if (!newPassword || newPassword.length < 12) {
   310|    throw new Error('A new password of at least 12 characters is required for supabase_reset_owner_password (enterprise policy).');
   311|  }
   312|  const admin = resolveSupabaseAdminClient();
   313|  const { data: listData, error: listError } = await admin.auth.admin.listUsers({ page: 1, perPage: 1000 });
   314|  if (listError) {
   315|    throw new Error(`Supabase listUsers failed: ${listError.message}`);
   316|  }
   317|  const user = (listData.users ?? []).find((u) => (u.email ?? '').toLowerCase() === email);
   318|  if (!user) {
   319|    throw new Error(`No Supabase auth user found for email ${email}.`);
   320|  }
   321|  const { data: updateData, error: updateError } = await admin.auth.admin.updateUserById(user.id, {
   322|    password: newPassword,
   323|    email_confirm: true,
   324|    ban_duration: 'none',
   325|  });
   326|  if (updateError || !updateData.user) {
   327|    throw new Error(`Supabase updateUserById failed: ${updateError?.message ?? 'no user returned'}`);
   328|  }
   329|  // SECURITY: revoke all existing sessions so any session bound to the old (compromised) password is killed.
   330|  try {
   331|    await admin.auth.admin.signOut(user.id, 'global');
   332|  } catch (signOutError) {
   333|    console.log('[SupabaseResetOwnerPassword] Session revocation note:', signOutError instanceof Error ? signOutError.message : 'unknown');
   334|  }
   335|  return {
   336|    provider: 'supabase',
   337|    action: 'supabase_reset_owner_password',
   338|    email,
   339|    userId: user.id,
