    83|
    84|async function githubRead(input: { operation?: string; branch?: string }): Promise<Omit<ToolResult, 'tool' | 'executedAt' | 'durationMs'>> {
    85|  const op = input.operation ?? 'status';
    86|  if (!githubToken()) return { ok: false, error: 'IVX_GITHUB_TOKEN (or GITHUB_TOKEN) not configured', data: null };
    87|
    88|  try {
    89|    switch (op) {
    90|      case 'branches': {
    91|        const result = await GitHubTool.getBranches();
    92|        return { ok: result.ok, error: result.error, data: { branches: result.branches } };
    93|      }
    94|      case 'status':
    95|      case 'info': {
    96|        const result = await GitHubTool.getFullGitHubStatus();
    97|        return { ok: result.ok, error: result.error, data: result };
    98|      }
    99|      case 'commit': {
   100|        const result = await GitHubTool.getLatestCommit(input.branch);
   101|        return { ok: result.ok, error: result.error, data: { commit: result.commit } };
   102|      }
   103|      case 'repo': {
   104|        const result = await GitHubTool.getRepoInfo();
   105|        return { ok: result.ok, error: result.error, data: { repo: result.repo } };
   106|      }
   107|      default:
   108|        return { ok: false, error: `Unknown github.read operation: ${op}`, data: null };
   109|    }
   110|  } catch (err) {
   111|    return { ok: false, error: err instanceof Error ? err.message : String(err), data: null };
   112|  }
   113|}
