     2| * IVX Amazon SES email sender (owner-only outreach delivery).
     3| *
     4| * Replaces SendGrid as the active outbound email path. Sends a single email via
     5| * the AWS SES v2 API (`/v2/email/outbound-emails`) using a SigV4-signed HTTPS
     6| * request — no new dependencies, same signing pattern as the CloudFront agent.
     7| *
     8| * Credentials come from the existing AWS env (AWS_ACCESS_KEY_ID /
     9| * AWS_SECRET_ACCESS_KEY / AWS_REGION). The verified sender address comes from
    10| * IVX_SES_FROM_EMAIL (falling back to OWNER_REPAIR_EMAIL / EXPO_PUBLIC_OWNER_EMAIL).
    11| *
    12| * SAFETY: callers must enforce owner approval before invoking this. This module
    13| * only performs the transport — it never decides whether a message may be sent.
    14| *
    15| * This file must be stored as plain TypeScript source. Encoding the full module
    16| * as base64 causes the production bundler to fail before the service can start.
    17| */
    18|import { createHash, createHmac } from 'node:crypto';
    19|
    20|const AWS_SERVICE = 'ses';
    21|
    22|export type SesSendResult = {
    23|  ok: boolean;
    24|  status: 'sent' | 'missing_config' | 'failed';
    25|  messageId?: string;
    26|  httpStatus?: number;
    27|  region?: string;
    28|  from?: string;
    29|  to?: string;
    30|  /** Exact env names still required to enable sending. */
    31|  missingEnvNames: string[];
    32|  error?: string;
    33|  sentAt: string;
    34|};
    35|
    36|function readEnv(name: string): string {
    37|  const v = process.env[name];
    38|  return typeof v === 'string' ? v.trim() : '';
    39|}
    40|
    41|function readRecord(value: unknown): Record<string, unknown> {
    42|  return typeof value === 'object' && value !== null ? (value as Record<string, unknown>) : {};
    43|}
    44|
    45|/** The verified SES sender address, with safe owner-email fallbacks. */
    46|export function resolveSesFromEmail(): string {
    47|  return (
    48|    readEnv('IVX_SES_FROM_EMAIL') ||
    49|    readEnv('OWNER_REPAIR_EMAIL') ||
    50|    readEnv('EXPO_PUBLIC_OWNER_EMAIL')
    51|  );
    52|}
    53|
    54|function resolveRegion(): string {
    55|  return readEnv('AWS_REGION') || 'us-east-1';
    56|}
    57|
    58|function hash(payload: string): string {
    59|  return createHash('sha256').update(payload, 'utf8').digest('hex');
    60|}
    61|
    62|function hmac(key: Buffer | string, data: string): Buffer {
    63|  return createHmac('sha256', key).update(data, 'utf8').digest();
    64|}
    65|
    66|function buildSigningKey(secret: string, dateStamp: string, region: string): Buffer {
    67|  const kDate = hmac(`AWS4${secret}`, dateStamp);
    68|  const kRegion = hmac(kDate, region);
    69|  const kService = hmac(kRegion, AWS_SERVICE);
    70|  return hmac(kService, 'aws4_request');
    71|}
    72|
    73|function isLikelyEmail(value: string): boolean {
    74|  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
    75|}
    76|
    77|/**
    78| * Request AWS SES to verify an email address as a sender/recipient identity.
    79| * AWS sends a verification email to the address; the recipient must click the
    80| * link before the address can be used to send or receive mail in sandbox mode.
    81| * Returns structured status; never throws.
    82| */
    83|export async function verifySesEmailIdentity(email: string): Promise<SesSendResult> {
    84|  const sentAt = new Date().toISOString();
    85|  const accessKey = readEnv('AWS_ACCESS_KEY_ID');
    86|  const secretKey = readEnv('AWS_SECRET_ACCESS_KEY');
    87|  const sessionToken = readEnv('AWS_SESSION_TOKEN');
    88|  const region = resolveRegion();
    89|  const target = email.trim().toLowerCase();
    90|
    91|  const missingEnvNames: string[] = [];
    92|  if (!accessKey) missingEnvNames.push('AWS_ACCESS_KEY_ID');
    93|  if (!secretKey) missingEnvNames.push('AWS_SECRET_ACCESS_KEY');
    94|
    95|  if (missingEnvNames.length > 0) {
    96|    return {
    97|      ok: false,
    98|      status: 'missing_config',
    99|      region,
   100|      to: target || undefined,
   101|      missingEnvNames,
   102|      error: 'Amazon SES is not fully configured.',
   103|      sentAt,
   104|    };
   105|  }
   106|
   107|  if (!isLikelyEmail(target)) {
   108|    return {
   109|      ok: false,
   110|      status: 'failed',
   111|      region,
   112|      to: target || undefined,
   113|      missingEnvNames,
   114|      error: 'Identity is not a valid email address.',
   115|      sentAt,
   116|    };
   117|  }
   118|
   119|  const host = `email.${region}.amazonaws.com`;
   120|  const canonicalUri = '/';
   121|  const action = 'VerifyEmailIdentity';
   122|  const payload = `Action=${encodeURIComponent(action)}&EmailAddress=${encodeURIComponent(target)}&Version=2010-12-01`;
   123|  const bodyHash = hash(payload);
   124|
   125|  const now = new Date();
   126|  const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, '');
   127|  const dateStamp = amzDate.slice(0, 8);
   128|  const contentType = 'application/x-www-form-urlencoded';
   129|  const headerLines: [string, string][] = [
   130|    ['content-type', contentType],
   131|    ['host', host],
   132|    ['x-amz-content-sha256', bodyHash],
   133|    ['x-amz-date', amzDate],
   134|  ];
   135|  if (sessionToken) headerLines.push(['x-amz-security-token', sessionToken]);
   136|  const canonicalHeaders = headerLines.map(([k, v]) => `${k}:${v}\n`).join('');
   137|  const signedHeaders = headerLines.map(([k]) => k).join(';');
   138|  const canonicalRequest = ['POST', canonicalUri, '', canonicalHeaders, signedHeaders, bodyHash].join('\n');
   139|  const credentialScope = `${dateStamp}/${region}/${AWS_SERVICE}/aws4_request`;
   140|  const stringToSign = ['AWS4-HMAC-SHA256', amzDate, credentialScope, hash(canonicalRequest)].join('\n');
   141|  const signingKey = buildSigningKey(secretKey, dateStamp, region);
   142|  const signature = createHmac('sha256', signingKey).update(stringToSign, 'utf8').digest('hex');
   143|  const authorization = `AWS4-HMAC-SHA256 Credential=${accessKey}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
   144|
   145|  const headers: Record<string, string> = {
   146|    'Content-Type': contentType,
   147|    Host: host,
   148|    'X-Amz-Content-Sha256': bodyHash,
   149|    'X-Amz-Date': amzDate,
   150|    Authorization: authorization,
   151|  };
   152|  if (sessionToken) headers['X-Amz-Security-Token'] = sessionToken;
   153|
   154|  try {
   155|    const response = await fetch(`https://${host}${canonicalUri}`, {
   156|      method: 'POST',
   157|      headers,
   158|      body: payload,
   159|    });
   160|    const text = await response.text();
   161|    if (!response.ok) {
   162|      return {
   163|        ok: false,
   164|        status: 'failed',
   165|        region,
   166|        to: target,
   167|        httpStatus: response.status,
   168|        missingEnvNames,
   169|        error: text.slice(0, 500) || `SES verification request responded ${response.status}`,
   170|        sentAt,
   171|      };
   172|    }
   173|    return {
   174|      ok: true,
   175|      status: 'sent',
   176|      region,
   177|      to: target,
   178|      httpStatus: response.status,
   179|      missingEnvNames,
   180|      sentAt,
   181|    };
   182|  } catch (error) {
   183|    return {
   184|      ok: false,
   185|      status: 'failed',
   186|      region,
   187|      to: target,
   188|      missingEnvNames,
   189|      error: error instanceof Error ? error.message : 'SES verification request failed.',
   190|      sentAt,
   191|    };
   192|  }
