   710|export async function getRegistrationMetrics(): Promise<RegistrationMetrics> {
   711|  if (!isDurableStoreConfigured()) {
   712|    return {
   713|      registrationsStarted: 0, registrationsCompleted: 0, registrationsFailed: 0,
   714|      abandonmentRate: 0, failureByStage: {}, failureByCode: {}, averageCompletionTimeMs: null,
   715|      duplicateAttempts: 0, rateLimitedAttempts: 0, emailConfirmationCompletionRate: null,
   716|      windowStart: new Date().toISOString(), windowEnd: new Date().toISOString(),
   717|      deploymentMarker: DEPLOYMENT_MARKER,
   718|    };
   719|  }
   720|  const all = await readDurableJson<Record<string, PersistedRegistrationState>>(REGISTRATION_STORE_FILE, {});
   721|  const states = Object.values(all);
   722|  const started = states.length;
   723|  const completed = states.filter((s) => s.finalStatus === 'completed').length;
   724|  const failed = states.filter((s) => s.finalStatus === 'failed').length;
   725|  const rateLimited = states.filter((s) => s.lastErrorCode === 'RATE_LIMITED').length;
   726|  const abandoned = states.filter((s) => s.finalStatus === 'pending' && (Date.now() - new Date(s.updatedAt).getTime()) > 30 * 60 * 1000).length;
   727|  const abandonedRate = started > 0 ? abandoned / started : 0;
   728|
   729|  const failureByStage: Record<string, number> = {};
   730|  const failureByCode: Record<string, number> = {};
   731|  for (const s of states) {
   732|    if (s.finalStatus === 'failed') {
   733|      failureByStage[s.stage] = (failureByStage[s.stage] || 0) + 1;
   734|      if (s.lastErrorCode) failureByCode[s.lastErrorCode] = (failureByCode[s.lastErrorCode] || 0) + 1;
   735|    }
   736|  }
   737|
   738|  // Average completion time (created → updated for completed)
   739|  let totalMs = 0, completedCount = 0;
   740|  for (const s of states) {
   741|    if (s.finalStatus === 'completed') {
   742|      const dur = new Date(s.updatedAt).getTime() - new Date(s.createdAt).getTime();
   743|      if (dur >= 0 && dur < 30 * 60 * 1000) { totalMs += dur; completedCount++; }
   744|    }
   745|  }
   746|  const avgMs = completedCount > 0 ? Math.round(totalMs / completedCount) : null;
   747|
   748|  // Email-confirmation completion rate: completed / (completed + pending at EMAIL_CONFIRMATION_REQUIRED)
   749|  const emailConfirmPending = states.filter((s) => s.stage === 'EMAIL_CONFIRMATION_REQUIRED' && s.finalStatus === 'pending').length;
   750|  const emailConfirmRate = (completed + emailConfirmPending) > 0 ? completed / (completed + emailConfirmPending) : null;
   751|
   752|  // Duplicate attempts: requests that were submitted more than once (by email hash)
   753|  const emailHashCounts: Record<string, number> = {};
   754|  for (const s of states) { emailHashCounts[s.normalizedEmailHash] = (emailHashCounts[s.normalizedEmailHash] || 0) + 1; }
