   757|  const timestamps = states.map((s) => new Date(s.createdAt).getTime()).sort();
   758|  const windowStart = timestamps.length > 0 ? new Date(timestamps[0]).toISOString() : new Date().toISOString();
   759|  const windowEnd = timestamps.length > 0 ? new Date(timestamps[timestamps.length - 1]).toISOString() : new Date().toISOString();
   760|
   761|  return {
   762|    registrationsStarted: started,
   763|    registrationsCompleted: completed,
   764|    registrationsFailed: failed,
   765|    abandonmentRate: Math.round(abandonedRate * 100) / 100,
   766|    failureByStage,
   767|    failureByCode,
   768|    averageCompletionTimeMs: avgMs,
   769|    duplicateAttempts,
   770|    rateLimitedAttempts: rateLimited,
   771|    emailConfirmationCompletionRate: emailConfirmRate !== null ? Math.round(emailConfirmRate * 100) / 100 : null,
